from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """
    rules: 辞書の順序付きリスト
    urls: URL文字列のリスト

    戻り値:
        書き換え後のURL、または block された場合は None のリスト
    """

    valid_match_types = {"path_prefix", "host", "query_param"}
    valid_actions = {
        "strip_prefix",
        "redirect_host",
        "add_query_param",
        "block",
    }

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        # 完全一致
        if host == match_value:
            return True

        # "*.example.com" は "a.example.com" には一致するが、
        # "example.com" 自体には一致しない
        if match_value.startswith("*."):
            suffix = match_value[2:]
            return host.endswith("." + suffix) and host != suffix

        return False

    def replace_host(parsed, new_host):
        """
        ホスト名だけを置き換え、ユーザー情報とポートは維持する。
        """
        userinfo = ""

        if parsed.username is not None:
            userinfo = parsed.username
            if parsed.password is not None:
                userinfo += ":" + parsed.password
            userinfo += "@"

        port = ""
        try:
            if parsed.port is not None:
                port = f":{parsed.port}"
        except ValueError:
            # 不正なポート番号は元のURLをそのまま使う
            port = ""

        # IPv6アドレスの場合は角括弧を付ける
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        netloc = f"{userinfo}{new_host}{port}"
        return parsed._replace(netloc=netloc)

    result = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten = parsed
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            if match_type not in valid_match_types:
                raise ValueError(f"不正な match_type: {match_type}")
            if action not in valid_actions:
                raise ValueError(f"不正な action: {action}")
            if action != "block" and "action_value" not in rule:
                raise ValueError(
                    f"action_value が必要です: action={action}"
                )

            is_match = False

            if match_type == "path_prefix":
                is_match = parsed.path.startswith(match_value)

            elif match_type == "host":
                is_match = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parsed.query,
                        keep_blank_values=True,
                    )
                }
                is_match = match_value in query_names

            if not is_match:
                continue

            matched = True

            if action == "block":
                rewritten = None

            elif action == "strip_prefix":
                prefix = rule["action_value"]
                path = parsed.path

                if path.startswith(prefix):
                    path = path[len(prefix):]

                if not path:
                    path = "/"

                rewritten = parsed._replace(path=path)

            elif action == "redirect_host":
                rewritten = replace_host(
                    parsed,
                    rule["action_value"],
                )

            elif action == "add_query_param":
                addition = rule["action_value"]
                query = parsed.query

                if query:
                    query = query + "&" + addition
                else:
                    query = addition

                rewritten = parsed._replace(query=query)

            # 最初に適合したルールだけを使用
            break

        if rewritten is None:
            result.append(None)
        elif matched:
            result.append(urlunsplit(rewritten))
        else:
            result.append(url)

    return result
